import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Checklist manuale — disegni e canvas (M3)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m3-drawings-canvas.md","filePath":"qa/m3-drawings-canvas.md"}'),l={name:"qa/m3-drawings-canvas.md"};function r(t,e,s,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="checklist-manuale-—-disegni-e-canvas-m3" tabindex="-1">Checklist manuale — disegni e canvas (M3) <a class="header-anchor" href="#checklist-manuale-—-disegni-e-canvas-m3" aria-label="Permalink to &quot;Checklist manuale — disegni e canvas (M3)&quot;">​</a></h1><p>Da eseguire sul webview reale (macOS, Windows, Linux). Gli e2e automatici (<code>yarn workspace @memobrain/desktop-frontend e2e</code>) coprono apertura, modifica, salvataggio, embed e l&#39;assenza di richieste di rete sul mock dei binding; qui si verifica ciò che solo il webview reale mostra. <strong>Eseguire con la rete scollegata.</strong></p><p>Segnare <code>[x]</code> con data e sistema operativo.</p><h2 id="disegni-excalidraw" tabindex="-1">Disegni (Excalidraw) <a class="header-anchor" href="#disegni-excalidraw" aria-label="Permalink to &quot;Disegni (Excalidraw)&quot;">​</a></h2><ul><li>[ ] Palette → &quot;Nuovo disegno&quot;: il file <code>Drawing …excalidraw</code> compare nell&#39;explorer e si apre in una tab; se invocato da una nota in modifica, la nota riceve <code>![[Drawing ….excalidraw]]</code>.</li><li>[ ] Il testo dei disegni usa i font di Excalidraw (Excalifont, Virgil…) anche offline: nessun quadratino o font di ripiego.</li><li>[ ] Disegno con forme, frecce, testo e un&#39;immagine incollata: dopo ~2 s &quot;Salvato&quot;; chiudi e riapri: identico.</li><li>[ ] Tema chiaro/scuro: l&#39;editor segue il tema dell&#39;app; lingua italiana/inglese.</li><li>[ ] Esporta → PNG 1×, 2×, 3× con e senza sfondo, SVG: i file compaiono accanto al disegno; &quot;Copia negli appunti&quot; incolla l&#39;immagine in un&#39;altra app.</li><li>[ ] Zen e Presenta (schermo intero in sola lettura; Esc per uscire).</li><li>[ ] Libreria: aggiungi un elemento, riapri il vault: presente; il file <code>excalidraw-library.json</code> nella cartella di configurazione del vault si sincronizza (e, dalla 1.6, si fonde forma per forma).</li><li>[ ] Disegno &gt; 10 MB: banner di avviso, il salvataggio funziona.</li><li>[ ] Vault privato bloccato: il disegno è in sola lettura.</li><li>[ ] Modifica del file dall&#39;esterno con la tab aperta e nessuna modifica locale: la tab mostra la nuova versione (anche sfondo e griglia); con modifiche locali non salvate: le due versioni si fondono (1.6, ADR-0054); se la fusione non è ammessa o non riesce: banner di conflitto con <em>Ricarica</em>, <em>Sovrascrivi</em> e <em>Tieni entrambe</em>.</li></ul><h2 id="navigazione-fusione-e-libreria-m18-1-6-adr-0053-adr-0054" tabindex="-1">Navigazione, fusione e libreria (M18, 1.6; ADR-0053, ADR-0054) <a class="header-anchor" href="#navigazione-fusione-e-libreria-m18-1-6-adr-0053-adr-0054" aria-label="Permalink to &quot;Navigazione, fusione e libreria (M18, 1.6; ADR-0053, ADR-0054)&quot;">​</a></h2><p>Da eseguire sul webview reale: gli e2e usano Chromium con i binding simulati e il core WASM, e il posizionamento dei pulsanti dipende dalle classi del fork di Excalidraw.</p><ul><li>[ ] In basso a sinistra, a destra del controllo dello zoom, ci sono <em>Zoom sulla selezione</em> e <em>Mini-mappa</em>: non coprono il controllo, seguono la sua larghezza quando cambia la percentuale e restano al loro posto cambiando la dimensione della finestra e lo zoom dell&#39;app.</li><li>[ ] <em>Zoom sulla selezione</em> con una forma selezionata la inquadra senza finire sotto la barra inferiore; senza selezione inquadra tutto il disegno; funziona anche in sola visualizzazione e su un vault in sola lettura.</li><li>[ ] <em>Mini-mappa</em>: un disegno grande, clic e trascinamento spostano la vista, le frecce (con Maiusc a passi più larghi) e Home funzionano con il focus sulla mini-mappa; si nasconde in Zen, in presentazione e mentre è aperto il menu degli stili (finestra bassa, 720 px); resta accesa o spenta dopo aver chiuso e riaperto l&#39;app, e non cambia su un altro dispositivo.</li><li>[ ] Disegno aperto in due pannelli: una modifica nel primo compare nel secondo; la scheda <em>Slide</em> della barra destra segue il pannello a fuoco e non resta vuota quando l&#39;altro pannello passa a un altro file.</li><li>[ ] Modificare il file fuori dall&#39;app (anche con la sincronizzazione) mentre ci sono modifiche non salvate: le due modifiche restano, senza banner; mentre si trascina una forma la fusione aspetta la fine del gesto. Un file ridotto a testo non valido: avviso con la sola scelta <em>Sovrascrivi</em> e il file non viene riscritto da solo.</li><li>[ ] Vault condiviso, una modifica di un altro utente a un disegno aperto con modifiche non salvate: banner con <em>Tieni entrambe</em> (la tua versione resta in una copia accanto al file).</li><li>[ ] <em>Annulla</em> dopo una modifica arrivata da fuori non la annulla; dopo un&#39;azione sulla scena la annulla in un passo.</li><li>[ ] Tema scuro e tema «Sistema» (cambiandolo dalle impostazioni del sistema operativo con l&#39;app aperta): gli embed di un disegno in una nota passano alla versione scura e viceversa; la stampa della nota usa la chiara.</li><li>[ ] La ricerca trova una parola che in un testo del disegno va a capo dentro la forma, e il TeX di una formula; dopo l&#39;aggiornamento dalla 1.5 il primo avvio rianalizza i disegni (può impiegare di più).</li><li>[ ] Libreria: aggiungere una forma in un pannello la mostra subito nell&#39;altro; due dispositivi che aggiungono forme diverse le tengono entrambe dopo la sincronizzazione.</li></ul><h2 id="azioni-sulla-scena-esportazione-e-strumenti-adr-0024" tabindex="-1">Azioni sulla scena, esportazione e strumenti (ADR-0024) <a class="header-anchor" href="#azioni-sulla-scena-esportazione-e-strumenti-adr-0024" aria-label="Permalink to &quot;Azioni sulla scena, esportazione e strumenti (ADR-0024)&quot;">​</a></h2><p>Da eseguire sul webview reale (gli e2e usano Chromium con i binding simulati).</p><ul><li>[ ] Palette → &quot;Disegno: apri il pannello strumenti&quot;: cerca, esegui un&#39;azione, aggiungi ai preferiti, riapri il vault: il preferito resta.</li><li>[ ] Boolean Operations (unione, intersezione, differenza, xor) su due forme sovrapposte; Split Ellipse: il risultato è corretto anche dopo la riapertura.</li><li>[ ] Auto Layout su un diagramma con frecce legate: le frecce seguono le forme; ridimensiona una forma con &quot;Imposta dimensioni&quot;: le frecce restano attaccate.</li><li>[ ] Mindmap da un testo-elenco indentato, calendario annuale e lineare, vignette, nuvolette, schema colori, linea organica.</li><li>[ ] Penne (fine, pennarello, evidenziatore) e puntatore laser: lo strumento cambia e il tratto ha stile e opacità attesi.</li><li>[ ] Menu ⋮ della barra: <em>Disegna per la forma</em> (Maiusc+X: un tratto diventa una forma), <em>Secchiello riempimento</em> (B: riempie forma/area cliccata), <em>Selezione a lazo</em> (seleziona gli elementi circondati). Barra e menu al 90%, senza il pulsante del menu principale; popover dei colori allineati.</li><li>[ ] Barra destra → <em>Slide</em> con un disegno di 3 cornici: miniature corrette, su/giù cambia l&#39;ordine di presentazione, l&#39;occhio esclude una cornice (&quot;2 di 3 incluse&quot;), le note del relatore si salvano e compaiono nella presentazione, Stampa produce un PDF con una cornice per pagina, ripetizione/contatore/note si applicano.</li><li>[ ] Presentazione con 3 cornici: frecce/Spazio/Pagina navigano con animazione, il selettore salta, Esc esce; in schermo intero la cornice si adatta. Senza cornici: presentazione semplice.</li><li>[ ] Esporta → PNG/SVG con selezione, cornice, scala e &quot;incorpora scena&quot;; &quot;Stampa / PDF…&quot; produce un PDF; &quot;Salva con nome…&quot; apre la finestra nativa.</li><li>[ ] Esportazione automatica (anche l&#39;override per singolo disegno): <code>Disegno.excalidraw.png/.svg</code> accanto al file 15 secondi dopo l&#39;ultimo salvataggio e subito alla chiusura del disegno (dalla 1.6, non a ogni salvataggio).</li><li>[ ] LaTeX (inserisci, doppio clic per modificare, reimposta dimensione) e Mermaid (testo → diagramma) senza richieste di rete.</li><li>[ ] Trascina dal file explorer sul canvas: immagine, nota (scheda) e altro disegno nel punto di rilascio.</li><li>[ ] Copia un <code>.excalidraw.md</code> dei plugin Excalidraw di terze parti (con un&#39;immagine incorporata) nel vault → &quot;Converti…&quot;: nasce <code>.excalidraw</code> accanto, apribile e con l&#39;immagine; l&#39;originale è intatto.</li><li>[ ] Importa un <code>.excalidrawlib</code> copiato nel vault: le forme compaiono nella libreria; &quot;Esporta la libreria&quot; crea <code>Library.excalidrawlib</code>.</li><li>[ ] Embed con <code>|left</code>, <code>|right-wrap</code> e <code>#frame=Nome</code>: allineamento e porzione corretti in Live Preview e Lettura.</li><li>[ ] Inserire un&#39;immagine oltre 10 MB è rifiutato con un messaggio chiaro; la ricerca trova il nome di una cornice.</li><li>[ ] Sul <strong>bundle di produzione</strong> nel webview reale (CSP stretta): formule LaTeX, Mermaid, PDF incorporati, grafo e font di Excalidraw funzionano senza richieste di rete e senza errori in console.</li><li>[ ] Presentazione con note del relatore: le note compaiono sotto la diapositiva; &quot;Descrivi il disegno come testo&quot; è leggibile con VoiceOver/NVDA.</li><li>[ ] Un profilo di configurazione con <code>drawing_latex: false</code> nasconde formule (comandi, doppio clic) e pannello Strumenti; <code>drawing_auto_export: false</code> ferma l&#39;esportazione automatica.</li><li>[ ] Rinomina una nota linkata da un elemento del disegno: il link nel <code>.excalidraw</code> è riscritto.</li></ul><h2 id="embed-e-ricerca" tabindex="-1">Embed e ricerca <a class="header-anchor" href="#embed-e-ricerca" aria-label="Permalink to &quot;Embed e ricerca&quot;">​</a></h2><ul><li>[ ] <code>![[disegno.excalidraw]]</code> e <code>![[disegno.excalidraw|400]]</code> in Live Preview e in Lettura: immagine con la larghezza richiesta; doppio clic apre il disegno.</li><li>[ ] Modifica il disegno e torna alla nota: l&#39;anteprima è aggiornata (nuova cache per hash).</li><li>[ ] Un elemento con link <code>[[Nota]]</code> compare nei Backlink della nota come &quot;Disegno: …&quot;.</li><li>[ ] La ricerca trova il testo scritto dentro il disegno.</li></ul><h2 id="canvas" tabindex="-1">Canvas <a class="header-anchor" href="#canvas" aria-label="Permalink to &quot;Canvas&quot;">​</a></h2><ul><li>[ ] Palette → &quot;Nuova lavagna&quot;: file <code>Canvas ….canvas</code>, tab con barra degli strumenti.</li><li>[ ] Doppio clic sulla lavagna aggiunge una scheda di testo; Markdown, math ed embed (<code>![[…]]</code>) si vedono a riposo.</li><li>[ ] Aggiungi nota, media (immagine, PDF, audio), link web, gruppo; ridimensiona dall&#39;angolo; trascina un gruppo: i nodi interni lo seguono.</li><li>[ ] Trascina da una maniglia di una scheda su un&#39;altra: nasce il collegamento; doppio clic sul collegamento per l&#39;etichetta.</li><li>[ ] Colori preset 1–6 su nodi e collegamenti; Annulla/Ripristina (⌘/Ctrl+Z, ⌘/Ctrl+Shift+Z); Elimina.</li><li>[ ] Zoom con pizzico/⌘+rotella, pan con trascinamento o rotella; &quot;Adatta al contenuto&quot;.</li><li>[ ] Un <code>.canvas</code> in formato JSON Canvas creato da un altro editor si apre e, riscritto da MemoBrain Notes, si riapre in quell&#39;editor senza perdite.</li><li>[ ] <code>![[mappa.canvas]]</code> in una nota: immagine statica; doppio clic apre la lavagna.</li></ul><h2 id="due-dispositivi" tabindex="-1">Due dispositivi <a class="header-anchor" href="#due-dispositivi" aria-label="Permalink to &quot;Due dispositivi&quot;">​</a></h2><ul><li>[ ] Disegno modificato in punti diversi sui due dispositivi: convergono senza copie di conflitto.</li><li>[ ] Stesso nodo di un canvas modificato su entrambi: una versione resta, l&#39;altra diventa una copia di conflitto; nulla va perso.</li></ul>',17)])])}const g=a(l,[["render",r]]);export{p as __pageData,g as default};
